// swift-tools-version:6.0
// OMC's Linux build. Build with
// ./build-linux.sh, which adds the CoreFoundation, blocks and module flags this manifest cannot
// express. On macOS this is an empty package: Xcode (CommandWorkshop.xcworkspace) is the build there.
//
// Each target's sources are one-line shims in Linux/Targets/<target>/ that include the real files
// where the Xcode projects keep them. They are generated by Linux/make-shims.sh from
// Linux/sources.txt: add a portable source there, not here, and rerun the script.

import PackageDescription

#if os(Linux)
import Foundation

// Where OMC's headers are: sources include them by bare name, as Xcode's header map lets them.
// Relative to a target folder, Linux/Targets/<target>/.
let headerFolders = [
    "../../../CommandFramework",
    "../../../CommandFramework/Platform",
    "../../../CommandFramework/EntryPoints/Linux",
    "../../../Common",
    "../../../Common/Linux",
    "../../../ThirdParty/yyjson",
    "../../../b64",
]

let version: [CSetting] = [
    .define("CURRENT_OMC_VERSION", to: "60000"),
    .define("MIN_OMC_VERSION", to: "30200"),
    .define("MIN_MAC_OS_VERSION", to: "0"), // no effect on Linux: the macOS version checks do not run there (OMCGetMacOSVersion); macOS: 140600, OmcVersion.xcconfig
    .define("MAX_MAC_OS_VERSION", to: "999999"),
    .define("_DEBUG_", to: "1", .when(configuration: .debug)),
    .define("OMC_TEST_SURFACE", to: "1", .when(configuration: .debug)), // the integration-test surface (Platform/Linux/OMCTestability.cpp): debug builds only
    .define("_TRACE_", to: "1", .when(configuration: .debug)),
    .define("_TRACE_", to: "0", .when(configuration: .release)),
    .define("DEBUG", to: "1", .when(configuration: .debug)),
    .define("_DEBUG_", to: "0", .when(configuration: .release)),
    .define("NDEBUG", to: "1", .when(configuration: .release)),
]

let cSettings: [CSetting] = headerFolders.map { .headerSearchPath($0) } + version

let cxxSettings: [CXXSetting] = headerFolders.map { .headerSearchPath($0) } + [
    .define("CURRENT_OMC_VERSION", to: "60000"),
    .define("MIN_OMC_VERSION", to: "30200"),
    .define("MIN_MAC_OS_VERSION", to: "0"), // no effect on Linux: the macOS version checks do not run there (OMCGetMacOSVersion); macOS: 140600, OmcVersion.xcconfig
    .define("MAX_MAC_OS_VERSION", to: "999999"),
    .define("_DEBUG_", to: "1", .when(configuration: .debug)),
    .define("OMC_TEST_SURFACE", to: "1", .when(configuration: .debug)), // the integration-test surface (Platform/Linux/OMCTestability.cpp): debug builds only
    .define("_TRACE_", to: "1", .when(configuration: .debug)),
    .define("_TRACE_", to: "0", .when(configuration: .release)),
    .define("DEBUG", to: "1", .when(configuration: .debug)),
    .define("_DEBUG_", to: "0", .when(configuration: .release)),
    .define("NDEBUG", to: "1", .when(configuration: .release)),
]

// CoreFoundation lives in Swift's Foundation on Linux; libdispatch and the blocks runtime beside it.
// C and C++ programs are linked by clang, which does not know where the Swift runtime is:
// build-linux.sh passes its folder (OMC_SWIFT_RUNTIME_LIB) for the -L and the runtime path.
let runtimeLibraryFolder = ProcessInfo.processInfo.environment["OMC_SWIFT_RUNTIME_LIB"] ?? "/usr/lib/swift/linux"
// The installed Swift runtime's folder (the command-engine-swift-<runtime version> package's),
// searched first: build-linux.sh gives it, and Linux/make-applet-bundle.sh trims a bundle's
// programs to it.
let engineRuntimeFolders = (ProcessInfo.processInfo.environment["COMMAND_ENGINE_SWIFT_FOLDER"].map { [$0] } ?? []) + [runtimeLibraryFolder]
let foundationLibraries: [LinkerSetting] = [
    .linkedLibrary("Foundation"),
    .linkedLibrary("dispatch"),
    .linkedLibrary("BlocksRuntime"),
    .linkedLibrary("m"),
    .unsafeFlags(["-L\(runtimeLibraryFolder)"] + engineRuntimeFolders.flatMap { ["-Xlinker", "-rpath", "-Xlinker", $0] }),
]

func tool(_ name: String, _ dependencies: [Target.Dependency]) -> Target {
    .executableTarget(
        name: name,
        dependencies: dependencies,
        path: "Linux/Targets/\(name)",
        cSettings: cSettings,
        cxxSettings: cxxSettings,
        linkerSettings: foundationLibraries
    )
}

let package = Package(
    name: "OMC",
    products: [
        // The engine: the counterpart of Command.framework's binary. Linked with -z defs, so a
        // platform function with no Linux implementation yet is a link error.
        .library(name: "Command", type: .dynamic, targets: ["Command"]),
        .executable(name: "plister", targets: ["plister"]),
        .executable(name: "b64", targets: ["b64"]),
        .executable(name: "filt", targets: ["filt"]),
        .executable(name: "loco", targets: ["loco"]),
        .executable(name: "omc_next_command", targets: ["omc_next_command"]),
        .executable(name: "omc_dialog_control", targets: ["omc_dialog_control"]),
        // The applet executable: copied into an applet bundle as its CFBundleExecutable, renamed
        // (Linux/make-applet-bundle.sh); build-linux.sh makes CommandApplet.app, the master applet
        .executable(name: "CommandApplet", targets: ["CommandApplet"]),
    ],
    dependencies: [
        .package(path: "../ActionUI"),
        // ActionUI's add-ons with a Linux element (OMCRegisterActionUIAddOns): each links ActionUI's
        // ActionUIStatic, the same ActionUI module as above, and most fetch a package from GitHub
        // (RichText, AsyncImageCache, DiffView), so the first build needs the network
        .package(path: "../ActionUI/Add-ons/ActionUIRichText"),
        .package(path: "../ActionUI/Add-ons/ActionUICachedImage"),
        .package(path: "../ActionUI/Add-ons/ActionUIDiff"),
        .package(path: "../ActionUI/Add-ons/ActionUIHostSurface"),
    ],
    targets: [
        .target(name: "CYYJSON", path: "Linux/Targets/CYYJSON", publicHeadersPath: ".", cSettings: cSettings),
        .target(name: "ABase64", path: "Linux/Targets/ABase64", publicHeadersPath: ".", cSettings: cSettings),
        .target(
            name: "OMCCommon",
            dependencies: ["CYYJSON"],
            path: "Linux/Targets/OMCCommon",
            publicHeadersPath: ".",
            cSettings: cSettings,
            cxxSettings: cxxSettings,
            linkerSettings: foundationLibraries
        ),
        .target(
            name: "Command",
            dependencies: [
                "OMCCommon",
                .product(name: "ActionUICAdapter", package: "ActionUI"),
                .product(name: "ActionUIRemote", package: "ActionUI"),
                .product(name: "ActionUIRichText", package: "ActionUIRichText"),
                .product(name: "ActionUICachedImage", package: "ActionUICachedImage"),
                .product(name: "ActionUIDiff", package: "ActionUIDiff"),
                .product(name: "ActionUIHostSurface", package: "ActionUIHostSurface"),
            ],
            path: "Linux/Targets/Command",
            publicHeadersPath: ".",
            cSettings: cSettings,
            cxxSettings: cxxSettings,
            linkerSettings: foundationLibraries + [
                .linkedLibrary("glib-2.0"),
                .linkedLibrary("gobject-2.0"),
                .linkedLibrary("gio-2.0"),
                .linkedLibrary("gtk-4"),
                .linkedLibrary("adwaita-1"),
                .unsafeFlags(["-Xlinker", "-z", "-Xlinker", "defs"]),
            ]
        ),
        tool("plister", ["OMCCommon", "ABase64"]),
        tool("b64", ["ABase64"]),
        tool("filt", []),
        tool("loco", []),
        tool("omc_next_command", ["OMCCommon"]),
        tool("omc_dialog_control", ["OMCCommon"]),
        tool("CommandApplet", ["Command"]),

        // Linux checks of what macOS covers with the XCTest suite: run each with its arguments
        // (build-linux.sh does not run them). Not shims: these exist only for Linux.
        .executableTarget(
            name: "OMCLinuxPortTests",
            dependencies: ["Command"],
            path: "Linux/Tests/OMCLinuxPortTests",
            cSettings: cSettings,
            cxxSettings: cxxSettings,
            linkerSettings: foundationLibraries + [.linkedLibrary("glib-2.0")]
        ),
        .executableTarget(
            name: "OMCLinuxUITests",
            dependencies: ["Command"],
            path: "Linux/Tests/OMCLinuxUITests",
            cSettings: cSettings,
            cxxSettings: cxxSettings,
            linkerSettings: foundationLibraries + [.linkedLibrary("glib-2.0"), .linkedLibrary("gobject-2.0"), .linkedLibrary("gtk-4"), .linkedLibrary("adwaita-1")]
        ),
    ],
    cLanguageStandard: .gnu11,
    cxxLanguageStandard: .gnucxx17
)

#else

let package = Package(name: "OMC")

#endif
